python3 - <<'PY'
import json, glob, re, collections
from pathlib import Path
norm = lambda s: re.sub(r"\s+", " ", s).strip()
atoms=[]
for f in sorted(glob.glob('workplan/pipeline-state-graph/atoms/atoms-*.jsonl')):
    for line in open(f, encoding='utf-8'):
        if line.strip(): atoms.append(json.loads(line))
# 1. line-number check: does the quote occur within +-3 lines of the cited line?
cache={}
def lines(p):
    if p not in cache: cache[p]=Path(p).read_text(encoding='utf-8',errors='replace').split('\n')
    return cache[p]
off=[]; nolinenum=0
for a in atoms:
    src=a['source']; m=re.match(r'([^:]+):(\d+)', src)
    if not m: nolinenum+=1; continue
    p,n=m.group(1),int(m.group(2))
    L=lines(p); q=norm(re.sub(r"^\s*>\s?", "", a['quote']))
    win=norm(" ".join(re.sub(r"^\s*>\s?", "", l) for l in L[max(0,n-4):n+3]))
    if q not in win:
        # find actual line
        full=[i+1 for i,l in enumerate(L) if q[:40] in norm(re.sub(r"^\s*>\s?", "", l))]
        off.append((a['id'], src, full[:3]))
print("atoms:",len(atoms),"no line number:",nolinenum,"quote NOT within +-3 lines of cited line:",len(off))
for x in off[:25]: print("  ",x)
# 2. duplicate quotes across atom ids
byq=collections.defaultdict(list)
for a in atoms: byq[norm(a['quote']).lower()].append(a['id'])
d={q:ids for q,ids in byq.items() if len(ids)>1}
print("duplicate-quote groups:",len(d))
